import unittest
from fares import settle_fares

class TestFaresGate(unittest.TestCase):
    def test_happy_two(self):
        self.assertEqual(settle_fares([{'passenger': 'h1', 'fare': '70', 'baggage': '30', 'passcode': '10234', 'sailed': '2023-04-12', 'voucher': '0'}, {'passenger': 'h2', 'fare': '50', 'baggage': '30', 'passcode': '40234', 'sailed': '2022-05-20', 'voucher': '0'}]), {'total_minor': 2900, 'billed': 2, 'excluded': [], 'fares': {'h1': 1217, 'h2': 1683}, 'per_class': {'youth': 1217, 'adult': 1683}, 'mean_minor': 1450})
    def test_chargeable_ceil(self):
        self.assertEqual(settle_fares([{'passenger': 'd1', 'fare': '70', 'baggage': '13', 'passcode': '10234', 'sailed': '2023-04-12', 'voucher': '0'}]), {'total_minor': 1100, 'billed': 1, 'excluded': [], 'fares': {'d1': 1100}, 'per_class': {'youth': 1100}, 'mean_minor': 1100})
    def test_rebate_cap(self):
        self.assertEqual(settle_fares([{'passenger': 'k1', 'fare': '250', 'baggage': '50', 'passcode': '10234', 'sailed': '2023-04-12', 'voucher': '0'}]), {'total_minor': 2580, 'billed': 1, 'excluded': [], 'fares': {'k1': 2580}, 'per_class': {'youth': 2580}, 'mean_minor': 2580})
    def test_class_edges(self):
        self.assertEqual(settle_fares([{'passenger': 'z1', 'fare': '70', 'baggage': '30', 'passcode': '18000', 'sailed': '2023-04-12', 'voucher': '0'}, {'passenger': 'z4', 'fare': '70', 'baggage': '30', 'passcode': '49000', 'sailed': '2023-04-12', 'voucher': '0'}, {'passenger': 'z6', 'fare': '70', 'baggage': '30', 'passcode': '73000', 'sailed': '2023-04-12', 'voucher': '0'}, {'passenger': 'z7', 'fare': '70', 'baggage': '30', 'passcode': '74000', 'sailed': '2023-04-12', 'voucher': '0'}]), {'total_minor': 14395, 'billed': 4, 'excluded': [], 'fares': {'z1': 1917, 'z4': 2920, 'z6': 4779, 'z7': 4779}, 'per_class': {'adult': 1917, 'resident': 2920, 'priority': 9558}, 'mean_minor': 3599})
